package io.lumine.mythic.lib.api.crafting.recipes; import net.minecraft.item.ItemStack; import java.util.*; import java.util.concurrent.ConcurrentHashMap; public class MythicCraftingManager { public static final ItemStack AIR=ItemStack.EMPTY; private static final Map<String,MythicRecipe> LOADED=new ConcurrentHashMap<>(); private static final Map<String,ArrayList<MythicRecipeBlueprint>> STATIONS=new ConcurrentHashMap<>(); public static void log(String s){System.getLogger("MythicLib-Crafting").log(System.Logger.Level.INFO,s);} public static MythicRecipe getLoadedRecipe(String id){return LOADED.get(id);} public static ArrayList<String> getLoadedRecipes(){return new ArrayList<>(LOADED.keySet());} public static void load(MythicRecipe r){LOADED.put(r.getName(),r);r.load();} public static void deployBlueprint(MythicRecipeBlueprint b,MythicRecipeStation s){deployBlueprint(b,s,"");} public static void deployBlueprint(MythicRecipeBlueprint b,MythicRecipeStation s,String key){STATIONS.computeIfAbsent(s.name()+":"+(key==null?"":key.toLowerCase(Locale.ROOT)),k->new ArrayList<>()).add(b);} public static ArrayList<MythicRecipeBlueprint> getStationRecipes(MythicRecipeStation s,String key){return new ArrayList<>(STATIONS.getOrDefault(s.name()+":"+(key==null?"":key.toLowerCase(Locale.ROOT)),new ArrayList<>()));} static void removeBlueprint(MythicRecipeBlueprint b){STATIONS.values().forEach(list->list.remove(b));} public static void clear(){STATIONS.clear();LOADED.clear();} }
